$map|Add-Member -NotePropertyName vm_conditional_timing -NotePropertyValue ([ordered]@{implementation='src/FruitMachineLab.Runtime/Mpu4VmConditionalTiming.cs';vm_effects='src/FruitMachineLab.Runtime/RecoveredScript.cs';synthetic_evidence='skill-cash/vm-conditional-synthetic.json';natural_evidence='skill-cash/vm-conditional-natural.json';verification='skill-cash/vm-conditional-verification.json';source_symbols=@('PULU','PULL_REGISTERS','SUB16','CMP16','INDEXED','LD16','ST16','cond_ne','cond_ge','cond_gt');scope='Seven token entries, fourteen pre-state-selected paths;376 injected native cases,12 natural uninterrupted paths,2 interrupted excluded';qualification='CPU work only: VM effects remain translated, IRQ scheduling remains captured, word effects are not instruction-stepped'})
$map|ConvertTo-Json -Depth 6|Set-Content $mapPath
$map|Add-Member -NotePropertyName calibrated_delay -NotePropertyValue ([ordered]@{implementation='src/FruitMachineLab.Runtime/Mpu4CalibratedDelay.cs';live='src/FruitMachineLab.Adders/SkillCashLiveSession.cs';occupancy='src/FruitMachineLab.Runtime/CapturedInterruptOccupancy.cs';evidence='skill-cash/calibrated-delay-timing.json';source_symbols=@('DEC8','BRANCH','BSR','PSHS','PULS','INDEXED');scope='Enabled7159/7164 delay;20 native calls,2068 inner passes; natural fixed-tone wait matches34276 CPU cycles plus23 full outer IRQs';qualification='Live tone wait uses source-derived work through recorded IRQ envelopes. Queue/cancel and other VM pacing retain captured adapters; no generated IRQ start claim.'})
$map|ConvertTo-Json -Depth 6|Set-Content $mapPath
